public static void main(String[] args) {
    test("returns the new balance", () -> eq(withdraw(1000, 300), 700));
    test("can empty the account", () -> eq(withdraw(1000, 1000), 0));
    test("declines with a checked exception", () ->
        raises(InsufficientFundsException.class, () -> withdraw(200, 500)));
    test("the exception carries the amounts", () -> {
        var e = raises(InsufficientFundsException.class, () -> withdraw(200, 500));
        eq(e.requested, 500);
        eq(e.available, 200);
    });
    test("a non-positive amount is a programming error", () -> {
        raises(IllegalArgumentException.class, () -> withdraw(1000, 0));
        raises(IllegalArgumentException.class, () -> withdraw(1000, -5));
    });
    test("tryWithdraw reports success", () -> eq(tryWithdraw(1000, 300), "ok: 700"));
    test("tryWithdraw reports a decline", () -> eq(tryWithdraw(200, 500), "declined: need 500, have 200"));
    test("tryWithdraw does not hide programming errors", () ->
        raises(IllegalArgumentException.class, () -> tryWithdraw(1000, -1)));
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("opens, copies and closes in reverse order", () -> {
        var log = new ArrayList<String>();
        copy(log, false, false);
        eq(log, List.of("open in", "open out", "copy", "close out", "close in"));
    });
    test("closes both when the copy fails", () -> {
        var log = new ArrayList<String>();
        raises(IOException.class, () -> copy(log, true, false));
        eq(log, List.of("open in", "open out", "copy", "close out", "close in"));
    });
    test("the copy failure reaches the caller", () -> {
        var log = new ArrayList<String>();
        raises(IOException.class, () -> copy(log, true, false), "copy failed");
    });
    test("a close failure during a failed copy is suppressed, not lost", () -> {
        var log = new ArrayList<String>();
        var e = raises(IOException.class, () -> copy(log, true, true));
        eq(e.getSuppressed().length, 1);
        eq(e.getSuppressed()[0].getMessage(), "closing out failed");
    });
    test("a close failure alone is the exception", () -> {
        var log = new ArrayList<String>();
        raises(IllegalStateException.class, () -> copy(log, false, true), "closing out failed");
    });
    test("in is closed even when out fails to close", () -> {
        var log = new ArrayList<String>();
        raises(IllegalStateException.class, () -> copy(log, false, true));
        eq(log.get(log.size() - 1), "close in");
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

